        return open(path).read()
    except IOError:
        sys.exit('missing file: ' + path)

output:
**Issue:** sys.exit() inside a reusable function.
**Why:** Library code should not terminate the interpreter; it makes the function untestable and unusable from notebooks or services.
**Fix:**
class ConfigError(Exception):
    pass

def load(path):
    try:
        with open(path) as f:
            return f.read()
    except OSError as e:
        raise ConfigError(f'missing file: {path}') from e

