**Why:** First deploy without the file crashes with an unhandled FileNotFoundError and an unhelpful traceback at import time.
**Fix:**
import os, json, logging

def load_settings():
    if not os.path.exists('settings.json'):
        logging.warning('settings.json missing; using defaults')
        return {}
    try:
        with open('settings.json') as f:
            return json.load(f)
    except json.JSONDecodeError as e:
        raise RuntimeError('settings.json is not valid JSON') from e

