**Issue:** Retry loop with no attempt limit and no backoff.
**Why:** A permanently dead host spins forever, pegging a worker; even transient errors are retried in a tight hot loop.
**Fix:**
import time

def download_all(urls, attempts=3):
    results = []
    for u in urls:
        for attempt in range(attempts):
            try:
                results.append(requests.get(u, timeout=10).content)
                break
            except requests.RequestException:
                if attempt == attempts - 1:
                    raise
                time.sleep(2 ** attempt)
    return results

