def connect():
    try:
        return make_socket()
    except SocketError:
        pass

def connect_with_retry():
    while True:
        try:
            return connect()
        except Exception:
            time.sleep(1)

output:
**Issue:** connect() converts a SocketError into None (pass), so the retry loop never sees a failure and returns None immediately.
**Why:** The retry wrapper retries only on exceptions; a swallowed error short-circuits it and None propagates.
**Fix:**
def connect():
    return make_socket()

def connect_with_retry(attempts=5):
    last = None
    for i in range(attempts):
        try:
            return connect()
        except SocketError as e:
            last = e
            time.sleep(2 ** i)
    raise RuntimeError('connect failed') from last

